from rdkit import Chem
from rdkit.Chem import AllChem
m=Chem.MolFromSmiles('O=C([O-])c1cccc(C(=O)[O-])n1.[O-]CC[O-].[O-2].[V+5]')
for a in m.GetAtoms():print(a.GetIdx(),a.GetSymbol(),a.GetFormalCharge(),[x.GetIdx() for x in a.GetNeighbors()])
r=Chem.RWMol(m)
idxv=next(a.GetIdx() for a in r.GetAtoms() if a.GetSymbol()=='V')
for a in m.GetAtoms():
 if a.GetSymbol()=='O' and a.GetFormalCharge()<0 or a.GetSymbol()=='N':
  r.AddBond(a.GetIdx(),idxv,Chem.BondType.DATIVE)
m=r.GetMol()
try:
 Chem.SanitizeMol(m)
 print(Chem.MolToSmiles(m));m=Chem.AddHs(m)
 for randomseed in [12,3]:
  x=AllChem.EmbedMolecule(m,randomSeed=randomseed,maxAttempts=300)
  print('embed',x)
  if x==0:
   Chem.MolToXYZFile(m,'complex0.xyz')
   print('UFF',AllChem.UFFHasAllMoleculeParams(m)); print('MMFF',AllChem.MMFFHasAllMoleculeParams(m))
except Exception as e:print('ERROR:',e)
from rdkit.Geometry import Point3D
coords={0:(834,403),1:(730,344),2:(730,225),3:(834,164),4:(834,72),5:(775,25),6:(893,25),7:(937,224),8:(1040,164),9:(1040,78),10:(1144,224),11:(1215,183),12:(1144,344),13:(1248,404),14:(1322,361),15:(1248,524),16:(1144,584),17:(1144,668),18:(1040,524),19:(1040,422),20:(936,584),21:(834,524),22:(730,584),23:(730,671),24:(626,524),25:(522,584),26:(626,404),27:(419,404),28:(419,524),29:(315,584),30:(211,524),31:(108,584),32:(211,404),33:(108,345),34:(315,344)}
centers={3:4,8:9,10:11,13:14,16:17,26:27}
conf=Chem.Conformer(m.GetNumAtoms());conf.Set3D(True)
for idx,(x,y) in coords.items():
 conf.SetAtomPosition(idx,Point3D(x/75,-y/75,-0.9 if idx in centers.values() else 0))
for a in m.GetAtoms():
 if a.GetSymbol()=='H':
  neighbor=a.GetNeighbors()[0].GetIdx()
  x,y=coords.get(neighbor,(0,0))
  conf.SetAtomPosition(a.GetIdx(), Point3D(x/75,-y/75,1.0 if neighbor in centers else 0))
m.AddConformer(conf)
Chem.AssignAtomChiralTagsFromStructure(m,replaceExistingTags=True)
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
for idx in centers:
 a=m.GetAtomWithIdx(idx)
 print('STEREO',idx,str(a.GetChiralTag()),a.GetProp('_CIPCode') if a.HasProp('_CIPCode') else '?')
print(Chem.MolToSmiles(Chem.RemoveHs(m)))
